import os
import sys
import pandas as pd
import numpy as np
from data_util import find_closest_elements

import pandas_market_calendars as mcal
import datetime

import traceback
from tqdm import tqdm

nyse = mcal.get_calendar('NYSE')
TOTAL_SECONDS_ONE_YEAR = 365*24*60*60 # total seconds

def get_market_open_close(day_stamp,no_tzinfo=True):
    early = nyse.schedule(start_date=day_stamp, end_date=day_stamp)
    if len(early) == 0:
        raise LookupError("market not open today!")
    market_open = list(early.to_dict()['market_open'].values())[0]
    market_close = list(early.to_dict()['market_close'].values())[0]
    if no_tzinfo:
        return market_open.replace(tzinfo=None),market_close.replace(tzinfo=None)
    else:
        return market_open,market_close

def get_expiry_tstamp(expiry):
    if not isinstance(expiry,str):
        return np.nan
    expiry = datetime.datetime.strptime(expiry,"%Y-%m-%d")
    _,expiry_tstamp = get_market_open_close(expiry)
    return expiry_tstamp.replace(tzinfo=None)

def get_annualized_time_to_expiration(row,expiry_mapper):
    if isinstance(row.expiry,str):
        expiry = row.expiry
    else:
        expiry = row.expiry.strftime("%Y-%m-%d")
    expiry_tstamp = expiry_mapper[expiry]
    sec_to_expiration = (expiry_tstamp-row.tstamp).total_seconds()
    atte = sec_to_expiration/TOTAL_SECONDS_ONE_YEAR
    return atte


COLUMNS = ['date', 'forward_price', 'tau', 'risk_free_rate', 'is_call', 'strike_price', 'option_price', 'log_moneyness', 'implied_volatility', 'delta', 'time_to_maturity']

ROOT_FOLDER = "/mnt/hd1/data/uw-options-cache/SPX"

def gen_data(dstamp):
    ticker = "SPXW"
    pq_file = os.path.join(ROOT_FOLDER,f"{dstamp}.parquet.gzip")
    df = pd.read_parquet(pq_file)
    print(list(df.underlying_symbol.unique()))
    print(df.shape)
    df=df[df.underlying_symbol==ticker]
    print(df.shape)
    
    if True:
        # drop where tstamp_sec with too few orders
        counts = df.drop_duplicates(['tstamp_sec', 'expiry', 'strike']).groupby('tstamp_sec').size()
        df = df[df.tstamp_sec.apply(lambda x: counts[x] > 20)]
        print(df.shape,'!!!!!!!!!!!!!1DROOPPPPPP')

    if len(df) == 0:
        return None

    df['date']=df.tstamp_sec
    df['forward_price']=df.underlying_price
    expiry_mapper = {x:get_expiry_tstamp(x) for x in df.expiry.unique()}
    df['tau']=df.apply(lambda x: get_annualized_time_to_expiration(x,expiry_mapper),axis=1)
    df['risk_free_rate']=1e-7
    df['is_call']=df.option_type.apply(lambda x: 1.0 if x == 'call' else -1.0)
    df['strike_price']=df.strike
    df['option_price']=df.price
    df['log_moneyness'] = np.log(df.underlying_price/df.strike)
    #df.implied_volatility # same name, no need to make new column
    #df.delta # same name, no need to make new column
    df['time_to_maturity']=((df.tau*TOTAL_SECONDS_ONE_YEAR)/(60*60*24))
    df = df[(df.tau>0)&(df.log_moneyness.notnull())]

    # attempt to continue using find_closest_elements
    df = df[COLUMNS]
    df = df.dropna()
    
    call_df = df[df.is_call==1].copy().reset_index()
    put_df = df[df.is_call==-1].copy().reset_index()

    target_ttms = [0,1,5]
    target_deltas = [0.5, 0.25, -0.25]
    tmp_df = call_df.groupby('date').apply(find_closest_elements, 'time_to_maturity', target_ttms, include_groups=False)
    reference_options = tmp_df.groupby(['date','time_to_maturity']).apply(find_closest_elements, 'delta', target_deltas, include_groups=False)
    call_df['is_ref'] = 0
    call_df.loc[reference_options.index.get_level_values(-1), 'is_ref'] = 1
    print(call_df.is_ref.sum(),len(call_df),'!!#########################')

    tmp_df = put_df.groupby('date').apply(find_closest_elements, 'time_to_maturity', target_ttms, include_groups=False)
    reference_options = tmp_df.groupby(['date','time_to_maturity']).apply(find_closest_elements, 'delta', target_deltas, include_groups=False)
    put_df['is_ref'] = 0
    put_df.loc[reference_options.index.get_level_values(-1), 'is_ref'] = 1
    print(put_df.is_ref.sum(),len(put_df),'!!#########################')

    return call_df, put_df

call_h5_file = "/mnt/hd2bak/scratch/spx_w_ref_call.h5"
put_h5_file = "/mnt/hd2bak/scratch/spx_w_ref_put.h5"
if os.path.exists(call_h5_file):
    raise ValueError(f"file found, delete first! {call_h5_file}")
if os.path.exists(call_h5_file):
    raise ValueError(f"file found, delete first! {put_h5_file}")

dstamp_list = []
for dstamp in tqdm(dtstamp_list):
    try:
        call_df, put_df = gen_data(dstamp)
        if call_df is None:
            continue
        if put_df is None:
            continue
        call_df.to_hdf(path_or_buf=call_h5_file, key='df', complevel=9, complib='blosc',append=True)
        put_df.to_hdf(path_or_buf=put_h5_file, key='df', complevel=9, complib='blosc',append=True)
    except:
        traceback.print_exc()
    dstamp_list.append(dstamp)

print(len(dstamp_list))
